#!/usr/bin/env python3
"""Own MIT eager scalar hb_defaultValue probes. External Harbour oracle only."""
from pathlib import Path
import argparse,subprocess,json,hashlib,os
p=argparse.ArgumentParser();p.add_argument('--compiler',required=True);p.add_argument('--baseline',required=True);p.add_argument('--hbmk2',required=True);p.add_argument('--output',required=True);a=p.parse_args();out=Path(a.output).resolve();out.mkdir(parents=True,exist_ok=False);rows=[];env=dict(os.environ,PATH='/tmp/toolchain/bin:'+os.environ['PATH'])
def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def run(cmd,w,label):
 r=subprocess.run(list(map(str,cmd)),capture_output=True,env=env,timeout=30)
 for ext,v in [('stdout',r.stdout),('stderr',r.stderr),('rc',str(r.returncode).encode())]:(w/(label+'.'+ext)).write_bytes(v)
 return r
programs={'getter-nil': 'function Main()\nlocal x:=NIL\n? hb_defaultValue(x,7),ValType(x)\nreturn nil\n', 'wrong-type': 'function Main()\nlocal x:="keep"\n? hb_defaultValue(x,7),ValType(x)\nreturn nil\n', 'bool-false': 'function Main()\nlocal x:=.F.\n? hb_defaultValue(x,.T.)\nreturn nil\n', 'eager-snapshot': 'function Main()\nlocal x:=2,k:=0\n? hb_defaultValue(x,(x:=7)),x,hb_defaultValue(x,(k:=k+1)),k\nreturn nil\n', 'numeric-kinds': 'function Main()\n? hb_defaultValue(2,7.5),hb_defaultValue(2.5,7),hb_defaultValue(9007199254740993,1.25)\nreturn nil\n', 'nil-default': 'function Main()\n? hb_defaultValue(2,NIL),hb_defaultValue("s",NIL)\nreturn nil\n', 'owned-preserve': 'function Main()\nlocal s:=Upper("old-value"),r,z\nr:=hb_defaultValue(s,"fallback")\ns:=Upper("new-value")\nz:=Upper("bad-value")\n? r,s,z\nreturn nil\n', 'owned-fallback': 'function Main()\nlocal x:=NIL,s:=Upper("old-value"),r,z\nr:=hb_defaultValue(x,s)\ns:=Upper("new-value")\nz:=Upper("bad-value")\n? r,s,z\nreturn nil\n', 'nested': 'function Main()\n? hb_defaultValue(hb_defaultValue(NIL,"hello"),"fallback")\nreturn nil\n', 'dyn-int': 'function Main()\nlocal x,y\nx:=42\ny:=hb_defaultValue(x,7)\n? y,x,ValType(y)\nreturn nil\n', 'dyn-float': 'function Main()\nlocal x,y\nx:=1.25\ny:=hb_defaultValue(x,7)\n? y,x,ValType(y)\nreturn nil\n', 'dyn-bool': 'function Main()\nlocal x,y\nx:=.F.\ny:=hb_defaultValue(x,.T.)\n? y,x,ValType(y)\nreturn nil\n', 'dyn-string': 'function Main()\nlocal x,y,z\nx:=Upper("old-value")\ny:=hb_defaultValue(x,"fallback")\nx:=Upper("new-value")\nz:=Upper("bad-value")\n? y,x,z\nreturn nil\n', 'dyn-default': 'function Main()\nlocal x,y,r\nx:="keep"\ny:=Upper("fallback")\nr:=hb_defaultValue(x,y)\ny:=nil\nx:=nil\n? r,ValType(r)\nreturn nil\n', 'dyn-mismatch': 'function Main()\nlocal x,y,r\nx:=.T.\ny:=Upper("fallback")\nr:=hb_defaultValue(x,y)\ny:=nil\nx:=nil\n? r,ValType(r)\nreturn nil\n', 'self-copy': 'function Main()\nlocal x\nx:=Upper("self")\nx:=hb_defaultValue(x,x)\n? x,ValType(x)\nreturn nil\n', 'owned-temporaries': 'function Main()\n? hb_defaultValue(Upper("chosen"),Upper("other")),hb_defaultValue(nil,Upper("fallback"))\nreturn nil\n', 'static-left-mutated': 'function Change(x)\n? x+0\nx:=7\nreturn 9\nfunction Main()\nlocal x:=2,r\nr:=hb_defaultValue(x,Change(@x))\n? r,x\nreturn nil\n', 'ordered-calls': 'function A()\n? "a"\nreturn 2\nfunction B()\n? "b"\nreturn 3\nfunction Main()\n? hb_defaultValue(A(),B())\nreturn nil\n', 'right-throws': 'function Boom()\nlocal a:={1},i:=2\nreturn a[i]\nfunction Main()\nlocal r:=0\nTRY\nr:=hb_defaultValue(Upper("temp"),Boom())\nCATCH e\n? "caught",r\nEND\nreturn nil\n', 'left-throws': 'function Boom()\nlocal a:={1},i:=2\nreturn a[i]\nfunction B()\n? "wrong"\nreturn 3\nfunction Main()\nTRY\n? hb_defaultValue(Boom(),B())\nCATCH e\n? "caught"\nEND\nreturn nil\n', 'nested-right-throws': 'function Boom()\nlocal a:={1},i:=2\nreturn a[i]\nfunction Main()\nTRY\n? hb_defaultValue(Upper("outer"),hb_defaultValue(Upper("inner"),Boom()))\nCATCH e\n? "caught"\nEND\nreturn nil\n', 'prefix-string-snapshot': 'function Main()\nlocal x,y\nx:=Upper("old-value")\n? hb_defaultValue(x,hb_defaultValue(nil,(y:=1))),x,y\nreturn nil\n', 'return': 'function Pick()\nlocal x\nx:=Upper("returned")\nreturn hb_defaultValue(x,"fallback")\nfunction Main()\n? Pick(),Pick()\nreturn nil\n', 'argument': 'function Show(x)\n? x,ValType(x)\nreturn nil\nfunction Main()\nShow(hb_defaultValue(nil,Upper("arg")))\nreturn nil\n', 'discard': 'function Main()\nhb_defaultValue(Upper("discard"),Upper("other"))\n? "done"\nreturn nil\n', 'numeric-provenance': 'function Main()\nlocal n:=2,k:=1\n? hb_defaultValue(2+0,7),hb_defaultValue(n+k,7),hb_defaultValue(2.500,7.00),hb_defaultValue(nil,7.00)\nreturn nil\n'}
programs['dyn-left-inline-snapshot']='function Main()\nlocal x\nx:=2\n? hb_defaultValue(x,(x:=7)),x\nreturn nil\n'
programs['string-left-consumed']='function Consume(s)\n? s\nreturn "fallback"\nfunction Main()\nlocal s:=Upper("old-value"),y,z\ny:=hb_defaultValue(s,Consume(s))\nz:=Upper("bad-value")\n? y,z\nreturn nil\n'
for name,text in programs.items():
 w=out/name;w.mkdir();src=w/'p.prg';src.write_text(text);oracle_src=src
 if '\nTRY\n' in text:
  oracle_src=w/'oracle.prg';oracle_src.write_text('\n'.join('BEGIN SEQUENCE WITH {|o| Break(o)}' if l=='TRY' else 'RECOVER' if l=='CATCH e' else 'END SEQUENCE' if l=='END' else l for l in text.split('\n')))
 row=dict(name=name,source_sha256=h(src),oracle_source_sha256=h(oracle_src),oracle_adapter=oracle_src!=src,results={})
 for label,cmd in [('base',[a.baseline,src,w/'base','--target=linux']),('int',[a.compiler,src,w/'int','--target=linux']),('ext',[a.compiler,src,w/'ext','--target=linux','--external-as']),('oracle',[a.hbmk2,oracle_src,'-quiet','-w0','-gtstd','-o'+str(w/'oracle')])]:
  b=run(cmd,w,label+'-build');rr=dict(build_rc=b.returncode)
  if not b.returncode:
   q=run([w/label],w,label+'-run');rr.update(run_rc=q.returncode,binary_sha256=h(w/label));(w/label).unlink()
  row['results'][label]=rr
 for label in ['oracle','int','ext']:assert row['results'][label]['build_rc']==0,(name,label,(w/(label+'-build.stderr')).read_text())
 for label in ['int','ext']:assert all((w/(label+'-run.'+ext)).read_bytes()==(w/('oracle-run.'+ext)).read_bytes() for ext in ['rc','stdout','stderr']),(name,label)
 rows.append(row);print(name,'EXACT int/ext',flush=True)
(out/'results.json').write_text(json.dumps(dict(compiler_sha256=h(Path(a.compiler)),baseline_sha256=h(Path(a.baseline)),runner_sha256=h(Path(__file__)),scope='Own scalar hb_defaultValue sources, int/ext exact rc/stdout/stderr against fresh external Harbour. Baseline rejection separate.',rows=rows),indent=2))
